<!doctype html><html><head><link rel="icon" type="image/png" href="{{ asset('img/fav.png') }}"><link rel="apple-touch-icon" href="{{ asset('img/fav.png') }}"><meta charset="utf-8"><title>Report Card</title><style>body{font-family:Arial;color:#1f2937;background:#f1f5f9}.card{max-width:800px;margin:25px auto;background:white;padding:35px;border-top:8px solid #facc15}.head{text-align:center;border-bottom:2px solid #1e293b;padding-bottom:15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:20px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:9px;text-align:left}th{background:#f8fafc}.blocked{padding:20px;background:#fff7ed;color:#9a3412;font-weight:bold}@media print{body{background:white}.card{margin:0}.print{display:none}}</style></head><body><main class="card"><div class="head"><h1>{{ $school->name }}</h1><p>{{ $school->motto }}<br>{{ $school->address }} · {{ $school->phone }}</p><h2>Academic Report Card</h2></div><div class="grid"><div><b>Learner:</b> {{ $student->name }}<br><b>Admission no:</b> {{ $student->admission_no }}<br><b>Class:</b> {{ $exam->schoolClass->name }}</div><div><b>Exam:</b> {{ $exam->name }}<br><b>Term:</b> {{ $exam->term->name }}, {{ $exam->term->year }}<br><b>Date:</b> {{ now()->format('d M Y') }}</div></div>@if($blocked)<div class="blocked">Results are withheld because this term has an outstanding fee balance. Please contact the bursar.</div>@else<table><thead><tr><th>Subject</th><th>Score</th><th>Percentage</th><th>Grade</th><th>Remark</th></tr></thead><tbody>@foreach($subjects as $item)<tr><td>{{ $item['paper']->subject->name }}</td><td>{{ $item['score'] }}/{{ $item['paper']->maximum_score }}</td><td>{{ $item['percentage'] }}%</td><td>{{ $item['grade']?->grade ?? '-' }}</td><td>{{ $item['grade']?->remark ?? '' }}</td></tr>@endforeach</tbody></table>@endif<p style="margin-top:35px">Class teacher signature: ____________________ &nbsp;&nbsp; Head teacher signature: ____________________</p><button class="print" onclick="window.print()">Print report card</button></main></body></html>
